insert into spark_grading_private.rubrics_v2(subject_id,paper_id,rubric_version,criteria,active,verification_status,expected_total_marks) values ('office-administration','OA-ORIGINAL-02-01','oa-source-rubric-v2-2026-10-26','[{"id":"OA-ORIGINAL-02-01-Q1::q1-a","maxMarks":4,"kind":"structured","sourceFormat":"oa-original-paper2","sourcePaperId":"OA-ORIGINAL-02-01","sourceQuestion":1,"sourcePartId":"q1-a","sourceVersion":"oa-paper2-original-2026-10-26-v1","sourceMarking":{"criteria":[{"id":"q1-a-c1","marks":1,"rule":"One distinct correct point (1 of 4); accept the alternatives in the source answer bank.","model":"The office collects information from customers, staff and suppliers.","alternatives":["The office receives business information."]},{"id":"q1-a-c2","marks":1,"rule":"One distinct correct point (2 of 4); accept the alternatives in the source answer bank.","model":"The office records information so that transactions and decisions can be traced.","alternatives":["The office captures details in its records."]},{"id":"q1-a-c3","marks":1,"rule":"One distinct correct point (3 of 4); accept the alternatives in the source answer bank.","model":"The office processes information into useful business documents and reports.","alternatives":["The office turns raw data into useful information."]},{"id":"q1-a-c4","marks":1,"rule":"One distinct correct point (4 of 4); accept the alternatives in the source answer bank.","model":"The office communicates information to people who need it.","alternatives":["The office distributes information."]}],"choiceBank":[{"model":"The office collects information from customers, staff and suppliers.","alternatives":["The office receives business information."]},{"model":"The office records information so that transactions and decisions can be traced.","alternatives":["The office captures details in its records."]},{"model":"The office processes information into useful business documents and reports.","alternatives":["The office turns raw data into useful information."]},{"model":"The office communicates information to people who need it.","alternatives":["The office distributes information."]},{"model":"The office stores records securely for later retrieval.","alternatives":[]},{"model":"The office safeguards business assets and confidential information.","alternatives":[]}]},"prompt":"State FOUR functions of a business office.","expectedAnswer":"The office collects information from customers, staff and suppliers.\nThe office records information so that transactions and decisions can be traced.\nThe office processes information into useful business documents and reports.\nThe office communicates information to people who need it.","rubricVersion":"oa-source-rubric-v2-2026-10-26"},{"id":"OA-ORIGINAL-02-01-Q1::q1-b","maxMarks":4,"kind":"structured","sourceFormat":"oa-original-paper2","sourcePaperId":"OA-ORIGINAL-02-01","sourceQuestion":1,"sourcePartId":"q1-b","sourceVersion":"oa-paper2-original-2026-10-26-v1","sourceMarking":{"criteria":[{"id":"q1-b-c1","marks":1,"rule":"One distinct correct point (1 of 4); accept the alternatives in the source answer bank.","model":"An advantage is that the employee can avoid the time and cost of travelling to work.","alternatives":[]},{"id":"q1-b-c2","marks":1,"rule":"One distinct correct point (2 of 4); accept the alternatives in the source answer bank.","model":"An advantage is that the organisation may need less office space.","alternatives":[]},{"id":"q1-b-c3","marks":1,"rule":"One distinct correct point (3 of 4); accept the alternatives in the source answer bank.","model":"A disadvantage is that an unreliable home internet connection can interrupt work.","alternatives":[]},{"id":"q1-b-c4","marks":1,"rule":"One distinct correct point (4 of 4); accept the alternatives in the source answer bank.","model":"A disadvantage is that face-to-face supervision and teamwork can be more difficult.","alternatives":[]}],"choiceBank":[{"model":"An advantage is that the employee can avoid the time and cost of travelling to work.","alternatives":[]},{"model":"An advantage is that the organisation may need less office space.","alternatives":[]},{"model":"A disadvantage is that an unreliable home internet connection can interrupt work.","alternatives":[]},{"model":"A disadvantage is that face-to-face supervision and teamwork can be more difficult.","alternatives":[]},{"model":"An advantage is that flexible scheduling can help the employee organise work and personal responsibilities.","alternatives":[]},{"model":"A disadvantage is that inadequate separation between home and work can cause distractions.","alternatives":[]}],"choiceRequirements":{"advantage":2,"disadvantage":2}},"prompt":"State TWO advantages and TWO disadvantages of allowing an employee to work from home. Give a different point in each case.","expectedAnswer":"An advantage is that the employee can avoid the time and cost of travelling to work.\nAn advantage is that the organisation may need less office space.\nA disadvantage is that an unreliable home internet connection can interrupt work.\nA disadvantage is that face-to-face supervision and teamwork can be more difficult.","rubricVersion":"oa-source-rubric-v2-2026-10-26"},{"id":"OA-ORIGINAL-02-01-Q1::q1-c","maxMarks":7,"kind":"structured","sourceFormat":"oa-original-paper2","sourcePaperId":"OA-ORIGINAL-02-01","sourceQuestion":1,"sourcePartId":"q1-c","sourceVersion":"oa-paper2-original-2026-10-26-v1","sourceMarking":{"criteria":[{"id":"q1-c-c1","marks":1,"rule":"Date and time: 18 May 2027, 10:20 a.m.","kind":"field","label":"Date and time","expected":"18 May 2027, 10:20 a.m.","alternatives":["18 May 2027 10:20 am"],"labelAliases":[],"model":"Date and time: 18 May 2027, 10:20 a.m."},{"id":"q1-c-c2","marks":1,"rule":"To: Mr Leon Brown","kind":"field","label":"To","expected":"Mr Leon Brown","alternatives":["Leon Brown","Mr Brown"],"labelAliases":[],"model":"To: Mr Leon Brown"},{"id":"q1-c-c3","marks":1,"rule":"Caller: Ms Keisha Cole","kind":"field","label":"Caller","expected":"Ms Keisha Cole","alternatives":["Keisha Cole","Ms Cole"],"labelAliases":[],"model":"Caller: Ms Keisha Cole"},{"id":"q1-c-c4","marks":1,"rule":"Organisation: Coral Stationery","kind":"field","label":"Organisation","expected":"Coral Stationery","alternatives":[],"labelAliases":[],"model":"Organisation: Coral Stationery"},{"id":"q1-c-c5","marks":1,"rule":"Telephone: 876-555-0147","kind":"field","label":"Telephone","expected":"876-555-0147","alternatives":["8765550147"],"labelAliases":[],"model":"Telephone: 876-555-0147"},{"id":"q1-c-c6","marks":1,"rule":"Message: Order 417 will arrive on 19 May instead of 18 May.","kind":"field","label":"Message","expected":"Order 417 will arrive on 19 May instead of 18 May.","alternatives":["Order 417 delivery changed from 18 May to 19 May."],"labelAliases":[],"model":"Message: Order 417 will arrive on 19 May instead of 18 May."},{"id":"q1-c-c7","marks":1,"rule":"Action required: Telephone Ms Cole by 3:00 p.m.","kind":"field","label":"Action required","expected":"Telephone Ms Cole by 3:00 p.m.","alternatives":["Call Keisha Cole by 3 pm.","Call Ms Cole by 15:00."],"labelAliases":[],"model":"Action required: Telephone Ms Cole by 3:00 p.m."}]},"prompt":"Prepare a telephone message for Mr Brown. Use these SEVEN labels: Date and time; To; Caller; Organisation; Telephone; Message; Action required.","expectedAnswer":"Date and time: 18 May 2027, 10:20 a.m.\nTo: Mr Leon Brown\nCaller: Ms Keisha Cole\nOrganisation: Coral Stationery\nTelephone: 876-555-0147\nMessage: Order 417 will arrive on 19 May instead of 18 May.\nAction required: Telephone Ms Cole by 3:00 p.m.","rubricVersion":"oa-source-rubric-v2-2026-10-26"},{"id":"OA-ORIGINAL-02-01-Q2::q2-a","maxMarks":3,"kind":"structured","sourceFormat":"oa-original-paper2","sourcePaperId":"OA-ORIGINAL-02-01","sourceQuestion":2,"sourcePartId":"q2-a","sourceVersion":"oa-paper2-original-2026-10-26-v1","sourceMarking":{"criteria":[{"id":"q2-a-c1","marks":1,"rule":"One distinct correct point (1 of 3); accept the alternatives in the source answer bank.","model":"Background noise can prevent a message from being heard clearly.","alternatives":[]},{"id":"q2-a-c2","marks":1,"rule":"One distinct correct point (2 of 3); accept the alternatives in the source answer bank.","model":"Unfamiliar jargon can prevent the receiver from understanding the message.","alternatives":[]},{"id":"q2-a-c3","marks":1,"rule":"One distinct correct point (3 of 3); accept the alternatives in the source answer bank.","model":"An unreliable internet connection can interrupt an online conversation.","alternatives":[]}],"choiceBank":[{"model":"Background noise can prevent a message from being heard clearly.","alternatives":[]},{"model":"Unfamiliar jargon can prevent the receiver from understanding the message.","alternatives":[]},{"model":"An unreliable internet connection can interrupt an online conversation.","alternatives":[]},{"model":"A language difference can cause a message to be misunderstood.","alternatives":[]},{"model":"Poor listening can cause important details to be missed.","alternatives":[]},{"model":"An unclear or incomplete message can confuse the receiver.","alternatives":[]}]},"prompt":"Identify THREE barriers to effective communication.","expectedAnswer":"Background noise can prevent a message from being heard clearly.\nUnfamiliar jargon can prevent the receiver from understanding the message.\nAn unreliable internet connection can interrupt an online conversation.","rubricVersion":"oa-source-rubric-v2-2026-10-26"},{"id":"OA-ORIGINAL-02-01-Q2::q2-b","maxMarks":4,"kind":"structured","sourceFormat":"oa-original-paper2","sourcePaperId":"OA-ORIGINAL-02-01","sourceQuestion":2,"sourcePartId":"q2-b","sourceVersion":"oa-paper2-original-2026-10-26-v1","sourceMarking":{"criteria":[{"id":"q2-b-c1","marks":1,"rule":"One distinct correct point (1 of 4); accept the alternatives in the source answer bank.","model":"A notice tells members when and where a meeting will take place.","alternatives":[]},{"id":"q2-b-c2","marks":1,"rule":"One distinct correct point (2 of 4); accept the alternatives in the source answer bank.","model":"An agenda lists the items to be considered at the meeting.","alternatives":[]},{"id":"q2-b-c3","marks":1,"rule":"One distinct correct point (3 of 4); accept the alternatives in the source answer bank.","model":"Minutes record the decisions and proceedings of a meeting.","alternatives":[]},{"id":"q2-b-c4","marks":1,"rule":"One distinct correct point (4 of 4); accept the alternatives in the source answer bank.","model":"An attendance register records the people present at the meeting.","alternatives":[]}],"choiceBank":[{"model":"A notice tells members when and where a meeting will take place.","alternatives":[]},{"model":"An agenda lists the items to be considered at the meeting.","alternatives":[]},{"model":"Minutes record the decisions and proceedings of a meeting.","alternatives":[]},{"model":"An attendance register records the people present at the meeting.","alternatives":[]},{"model":"Supporting papers provide information needed to discuss an agenda item.","alternatives":[]}]},"prompt":"State the purpose of EACH of FOUR documents used to prepare for or record a meeting.","expectedAnswer":"A notice tells members when and where a meeting will take place.\nAn agenda lists the items to be considered at the meeting.\nMinutes record the decisions and proceedings of a meeting.\nAn attendance register records the people present at the meeting.","rubricVersion":"oa-source-rubric-v2-2026-10-26"},{"id":"OA-ORIGINAL-02-01-Q2::q2-c","maxMarks":8,"kind":"structured","sourceFormat":"oa-original-paper2","sourcePaperId":"OA-ORIGINAL-02-01","sourceQuestion":2,"sourcePartId":"q2-c","sourceVersion":"oa-paper2-original-2026-10-26-v1","sourceMarking":{"criteria":[{"id":"q2-c-c1","marks":1,"rule":"Committee: Harbour View staff welfare committee","kind":"field","label":"Committee","expected":"Harbour View staff welfare committee","alternatives":["Staff welfare committee"],"labelAliases":[],"model":"Committee: Harbour View staff welfare committee"},{"id":"q2-c-c2","marks":1,"rule":"Date: 24 May 2027","kind":"field","label":"Date","expected":"24 May 2027","alternatives":[],"labelAliases":[],"model":"Date: 24 May 2027"},{"id":"q2-c-c3","marks":1,"rule":"Time: 2:00 p.m.","kind":"field","label":"Time","expected":"2:00 p.m.","alternatives":["2 pm","14:00"],"labelAliases":[],"model":"Time: 2:00 p.m."},{"id":"q2-c-c4","marks":1,"rule":"Venue: Training Room","kind":"field","label":"Venue","expected":"Training Room","alternatives":[],"labelAliases":[],"model":"Venue: Training Room"},{"id":"q2-c-c5","marks":1,"rule":"Opening: Welcome and apologies for absence","kind":"field","label":"Opening","expected":"Welcome and apologies for absence","alternatives":["Welcome; apologies for absence"],"labelAliases":[],"model":"Opening: Welcome and apologies for absence"},{"id":"q2-c-c6","marks":1,"rule":"Previous minutes: Read and approve the previous minutes","kind":"field","label":"Previous minutes","expected":"Read and approve the previous minutes","alternatives":["Approval of the previous minutes"],"labelAliases":[],"model":"Previous minutes: Read and approve the previous minutes"},{"id":"q2-c-c7","marks":1,"rule":"Budget: Review the sports-day budget","kind":"field","label":"Budget","expected":"Review the sports-day budget","alternatives":["Sports-day budget review"],"labelAliases":[],"model":"Budget: Review the sports-day budget"},{"id":"q2-c-c8","marks":1,"rule":"Volunteer duties: Decide how to allocate volunteer duties","kind":"field","label":"Volunteer duties","expected":"Decide how to allocate volunteer duties","alternatives":["Allocate volunteer duties"],"labelAliases":[],"model":"Volunteer duties: Decide how to allocate volunteer duties"}]},"prompt":"Prepare a short agenda for the committee meeting. Use these EIGHT labels: Committee; Date; Time; Venue; Opening; Previous minutes; Budget; Volunteer duties. Under Opening include apologies for absence.","expectedAnswer":"Committee: Harbour View staff welfare committee\nDate: 24 May 2027\nTime: 2:00 p.m.\nVenue: Training Room\nOpening: Welcome and apologies for absence\nPrevious minutes: Read and approve the previous minutes\nBudget: Review the sports-day budget\nVolunteer duties: Decide how to allocate volunteer duties","rubricVersion":"oa-source-rubric-v2-2026-10-26"},{"id":"OA-ORIGINAL-02-01-Q3::q3-a","maxMarks":3,"kind":"structured","sourceFormat":"oa-original-paper2","sourcePaperId":"OA-ORIGINAL-02-01","sourceQuestion":3,"sourcePartId":"q3-a","sourceVersion":"oa-paper2-original-2026-10-26-v1","sourceMarking":{"criteria":[{"id":"q3-a-c1","marks":1,"rule":"One distinct correct point (1 of 3); accept the alternatives in the source answer bank.","model":"A valid passport may be required to establish identity and nationality.","alternatives":[]},{"id":"q3-a-c2","marks":1,"rule":"One distinct correct point (2 of 3); accept the alternatives in the source answer bank.","model":"A visa may be required for permission to enter the destination country.","alternatives":[]},{"id":"q3-a-c3","marks":1,"rule":"One distinct correct point (3 of 3); accept the alternatives in the source answer bank.","model":"A travel insurance document provides details of the insurance cover.","alternatives":[]}],"choiceBank":[{"model":"A valid passport may be required to establish identity and nationality.","alternatives":[]},{"model":"A visa may be required for permission to enter the destination country.","alternatives":[]},{"model":"A travel insurance document provides details of the insurance cover.","alternatives":[]},{"model":"An airline ticket or booking confirmation provides the flight details.","alternatives":[]},{"model":"A health certificate may be required by the destination country.","alternatives":[]}]},"prompt":"Identify THREE documents that may be needed for international business travel and state a different document in each case.","expectedAnswer":"A valid passport may be required to establish identity and nationality.\nA visa may be required for permission to enter the destination country.\nA travel insurance document provides details of the insurance cover.","rubricVersion":"oa-source-rubric-v2-2026-10-26"},{"id":"OA-ORIGINAL-02-01-Q3::q3-b","maxMarks":4,"kind":"structured","sourceFormat":"oa-original-paper2","sourcePaperId":"OA-ORIGINAL-02-01","sourceQuestion":3,"sourcePartId":"q3-b","sourceVersion":"oa-paper2-original-2026-10-26-v1","sourceMarking":{"criteria":[{"id":"q3-b-c1","marks":1,"rule":"One distinct correct point (1 of 4); accept the alternatives in the source answer bank.","model":"A record is created or received when the business activity takes place.","alternatives":[]},{"id":"q3-b-c2","marks":1,"rule":"One distinct correct point (2 of 4); accept the alternatives in the source answer bank.","model":"The record is classified and stored so that it can be found.","alternatives":[]},{"id":"q3-b-c3","marks":1,"rule":"One distinct correct point (3 of 4); accept the alternatives in the source answer bank.","model":"The record is used and maintained while it is needed for business purposes.","alternatives":[]},{"id":"q3-b-c4","marks":1,"rule":"One distinct correct point (4 of 4); accept the alternatives in the source answer bank.","model":"The record is retained, archived or securely disposed of according to the retention schedule.","alternatives":[]}],"choiceBank":[{"model":"A record is created or received when the business activity takes place.","alternatives":[]},{"model":"The record is classified and stored so that it can be found.","alternatives":[]},{"model":"The record is used and maintained while it is needed for business purposes.","alternatives":[]},{"model":"The record is retained, archived or securely disposed of according to the retention schedule.","alternatives":[]}]},"prompt":"Outline FOUR stages in the life cycle of a business record.","expectedAnswer":"A record is created or received when the business activity takes place.\nThe record is classified and stored so that it can be found.\nThe record is used and maintained while it is needed for business purposes.\nThe record is retained, archived or securely disposed of according to the retention schedule.","rubricVersion":"oa-source-rubric-v2-2026-10-26"},{"id":"OA-ORIGINAL-02-01-Q3::q3-c","maxMarks":8,"kind":"structured","sourceFormat":"oa-original-paper2","sourcePaperId":"OA-ORIGINAL-02-01","sourceQuestion":3,"sourcePartId":"q3-c","sourceVersion":"oa-paper2-original-2026-10-26-v1","sourceMarking":{"criteria":[{"id":"q3-c-c1","marks":1,"rule":"Traveller: Ms Paula James","kind":"field","label":"Traveller","expected":"Ms Paula James","alternatives":["Paula James"],"labelAliases":[],"model":"Traveller: Ms Paula James"},{"id":"q3-c-c2","marks":1,"rule":"Outward flight: CJ204, Kingston, 6 June 2027, 8:00 a.m.","kind":"field","label":"Outward flight","expected":"CJ204, Kingston, 6 June 2027, 8:00 a.m.","alternatives":["CJ204 from Kingston on 6 June 2027 at 8 am"],"labelAliases":[],"model":"Outward flight: CJ204, Kingston, 6 June 2027, 8:00 a.m."},{"id":"q3-c-c3","marks":1,"rule":"Arrival: Bridgetown, 6 June 2027, 11:15 a.m.","kind":"field","label":"Arrival","expected":"Bridgetown, 6 June 2027, 11:15 a.m.","alternatives":["Bridgetown on 6 June 2027 at 11:15 am"],"labelAliases":[],"model":"Arrival: Bridgetown, 6 June 2027, 11:15 a.m."},{"id":"q3-c-c4","marks":1,"rule":"Hotel: Palm Court Hotel, two nights","kind":"field","label":"Hotel","expected":"Palm Court Hotel, two nights","alternatives":["Palm Court Hotel for 2 nights"],"labelAliases":[],"model":"Hotel: Palm Court Hotel, two nights"},{"id":"q3-c-c5","marks":1,"rule":"Airport transfer: Car collection at Bridgetown airport","kind":"field","label":"Airport transfer","expected":"Car collection at Bridgetown airport","alternatives":["Car booked at Bridgetown airport"],"labelAliases":[],"model":"Airport transfer: Car collection at Bridgetown airport"},{"id":"q3-c-c6","marks":1,"rule":"Workshop date and place: 7 June 2027, Trade Centre","kind":"field","label":"Workshop date and place","expected":"7 June 2027, Trade Centre","alternatives":["Trade Centre on 7 June 2027"],"labelAliases":[],"model":"Workshop date and place: 7 June 2027, Trade Centre"},{"id":"q3-c-c7","marks":1,"rule":"Workshop time: 9:00 a.m.–4:00 p.m.","kind":"field","label":"Workshop time","expected":"9:00 a.m.–4:00 p.m.","alternatives":["9 am to 4 pm","09:00 to 16:00"],"labelAliases":[],"model":"Workshop time: 9:00 a.m.–4:00 p.m."},{"id":"q3-c-c8","marks":1,"rule":"Return flight: CJ205, 8 June 2027, 12 noon","kind":"field","label":"Return flight","expected":"CJ205, 8 June 2027, 12 noon","alternatives":["CJ205 on 8 June 2027 at noon","CJ205 8 June 2027 12:00 pm"],"labelAliases":[],"model":"Return flight: CJ205, 8 June 2027, 12 noon"}]},"prompt":"Prepare the itinerary using these EIGHT labels: Traveller; Outward flight; Arrival; Hotel; Airport transfer; Workshop date and place; Workshop time; Return flight.","expectedAnswer":"Traveller: Ms Paula James\nOutward flight: CJ204, Kingston, 6 June 2027, 8:00 a.m.\nArrival: Bridgetown, 6 June 2027, 11:15 a.m.\nHotel: Palm Court Hotel, two nights\nAirport transfer: Car collection at Bridgetown airport\nWorkshop date and place: 7 June 2027, Trade Centre\nWorkshop time: 9:00 a.m.–4:00 p.m.\nReturn flight: CJ205, 8 June 2027, 12 noon","rubricVersion":"oa-source-rubric-v2-2026-10-26"},{"id":"OA-ORIGINAL-02-01-Q4::q4-a","maxMarks":3,"kind":"structured","sourceFormat":"oa-original-paper2","sourcePaperId":"OA-ORIGINAL-02-01","sourceQuestion":4,"sourcePartId":"q4-a","sourceVersion":"oa-paper2-original-2026-10-26-v1","sourceMarking":{"criteria":[{"id":"q4-a-c1","marks":1,"rule":"One distinct correct point (1 of 3); accept the alternatives in the source answer bank.","model":"The organisation prepares a job description and person specification.","alternatives":[]},{"id":"q4-a-c2"