insert into spark_grading_private.rubrics_v2(subject_id,paper_id,rubric_version,criteria,active,verification_status,expected_total_marks) values ('office-administration','OA-ORIGINAL-02-03','oa-source-rubric-v2-2026-10-26','[{"id":"OA-ORIGINAL-02-03-Q1::q1-a","maxMarks":4,"kind":"structured","sourceFormat":"oa-original-paper2","sourcePaperId":"OA-ORIGINAL-02-03","sourceQuestion":1,"sourcePartId":"q1-a","sourceVersion":"oa-paper2-original-2026-10-26-v1","sourceMarking":{"criteria":[{"id":"q1-a-c1","marks":1,"rule":"One distinct correct point (1 of 4); accept the alternatives in the source answer bank.","model":"The employee arrives on time and meets agreed work deadlines.","alternatives":[]},{"id":"q1-a-c2","marks":1,"rule":"One distinct correct point (2 of 4); accept the alternatives in the source answer bank.","model":"The employee handles confidential information responsibly.","alternatives":[]},{"id":"q1-a-c3","marks":1,"rule":"One distinct correct point (3 of 4); accept the alternatives in the source answer bank.","model":"The employee communicates courteously with colleagues and customers.","alternatives":[]},{"id":"q1-a-c4","marks":1,"rule":"One distinct correct point (4 of 4); accept the alternatives in the source answer bank.","model":"The employee takes responsibility for accurate work and corrects errors honestly.","alternatives":[]}],"choiceBank":[{"model":"The employee arrives on time and meets agreed work deadlines.","alternatives":[]},{"model":"The employee handles confidential information responsibly.","alternatives":[]},{"model":"The employee communicates courteously with colleagues and customers.","alternatives":[]},{"model":"The employee takes responsibility for accurate work and corrects errors honestly.","alternatives":[]},{"model":"The employee follows lawful organisational rules and procedures.","alternatives":[]},{"model":"The employee cooperates with others and treats them respectfully.","alternatives":[]}]},"prompt":"State FOUR characteristics of a professional office employee.","expectedAnswer":"The employee arrives on time and meets agreed work deadlines.\nThe employee handles confidential information responsibly.\nThe employee communicates courteously with colleagues and customers.\nThe employee takes responsibility for accurate work and corrects errors honestly.","rubricVersion":"oa-source-rubric-v2-2026-10-26"},{"id":"OA-ORIGINAL-02-03-Q1::q1-b","maxMarks":4,"kind":"structured","sourceFormat":"oa-original-paper2","sourcePaperId":"OA-ORIGINAL-02-03","sourceQuestion":1,"sourcePartId":"q1-b","sourceVersion":"oa-paper2-original-2026-10-26-v1","sourceMarking":{"criteria":[{"id":"q1-b-c1","marks":1,"rule":"One distinct correct point (1 of 4); accept the alternatives in the source answer bank.","model":"The chart shows the reporting relationship between employees and supervisors.","alternatives":[]},{"id":"q1-b-c2","marks":1,"rule":"One distinct correct point (2 of 4); accept the alternatives in the source answer bank.","model":"The chart shows the departments or sections within the organisation.","alternatives":[]},{"id":"q1-b-c3","marks":1,"rule":"One distinct correct point (3 of 4); accept the alternatives in the source answer bank.","model":"The chart helps the employee identify the proper line of communication.","alternatives":[]},{"id":"q1-b-c4","marks":1,"rule":"One distinct correct point (4 of 4); accept the alternatives in the source answer bank.","model":"The chart shows levels of authority and responsibility.","alternatives":[]}],"choiceBank":[{"model":"The chart shows the reporting relationship between employees and supervisors.","alternatives":[]},{"model":"The chart shows the departments or sections within the organisation.","alternatives":[]},{"model":"The chart helps the employee identify the proper line of communication.","alternatives":[]},{"model":"The chart shows levels of authority and responsibility.","alternatives":[]},{"model":"The chart helps the employee identify colleagues with relevant responsibilities.","alternatives":[]}]},"prompt":"State FOUR benefits of an organisation chart to an office employee.","expectedAnswer":"The chart shows the reporting relationship between employees and supervisors.\nThe chart shows the departments or sections within the organisation.\nThe chart helps the employee identify the proper line of communication.\nThe chart shows levels of authority and responsibility.","rubricVersion":"oa-source-rubric-v2-2026-10-26"},{"id":"OA-ORIGINAL-02-03-Q1::q1-c","maxMarks":7,"kind":"structured","sourceFormat":"oa-original-paper2","sourcePaperId":"OA-ORIGINAL-02-03","sourceQuestion":1,"sourcePartId":"q1-c","sourceVersion":"oa-paper2-original-2026-10-26-v1","sourceMarking":{"criteria":[{"id":"q1-c-c1","marks":1,"rule":"Date and time: 4 November 2027, 11:40 a.m.","kind":"field","label":"Date and time","expected":"4 November 2027, 11:40 a.m.","alternatives":["4 November 2027 11:40 am"],"labelAliases":[],"model":"Date and time: 4 November 2027, 11:40 a.m."},{"id":"q1-c-c2","marks":1,"rule":"To: Mr David Bell","kind":"field","label":"To","expected":"Mr David Bell","alternatives":["David Bell","Mr Bell"],"labelAliases":[],"model":"To: Mr David Bell"},{"id":"q1-c-c3","marks":1,"rule":"Caller: Mr Peter Hall","kind":"field","label":"Caller","expected":"Mr Peter Hall","alternatives":["Peter Hall"],"labelAliases":[],"model":"Caller: Mr Peter Hall"},{"id":"q1-c-c4","marks":1,"rule":"Organisation: Eastern Printing","kind":"field","label":"Organisation","expected":"Eastern Printing","alternatives":[],"labelAliases":[],"model":"Organisation: Eastern Printing"},{"id":"q1-c-c5","marks":1,"rule":"Telephone: 758-555-0186","kind":"field","label":"Telephone","expected":"758-555-0186","alternatives":["7585550186"],"labelAliases":[],"model":"Telephone: 758-555-0186"},{"id":"q1-c-c6","marks":1,"rule":"Message: Brochure proof B62 needs approval so printing can start tomorrow.","kind":"field","label":"Message","expected":"Brochure proof B62 needs approval so printing can start tomorrow.","alternatives":["Approval is needed for brochure proof B62 before printing tomorrow."],"labelAliases":[],"model":"Message: Brochure proof B62 needs approval so printing can start tomorrow."},{"id":"q1-c-c7","marks":1,"rule":"Action required: Telephone Mr Hall by 2:00 p.m. today.","kind":"field","label":"Action required","expected":"Telephone Mr Hall by 2:00 p.m. today.","alternatives":["Call Peter Hall by 2 pm on 4 November 2027.","Call Mr Hall by 14:00 today."],"labelAliases":[],"model":"Action required: Telephone Mr Hall by 2:00 p.m. today."}]},"prompt":"Prepare the telephone message using these SEVEN labels: Date and time; To; Caller; Organisation; Telephone; Message; Action required.","expectedAnswer":"Date and time: 4 November 2027, 11:40 a.m.\nTo: Mr David Bell\nCaller: Mr Peter Hall\nOrganisation: Eastern Printing\nTelephone: 758-555-0186\nMessage: Brochure proof B62 needs approval so printing can start tomorrow.\nAction required: Telephone Mr Hall by 2:00 p.m. today.","rubricVersion":"oa-source-rubric-v2-2026-10-26"},{"id":"OA-ORIGINAL-02-03-Q2::q2-a","maxMarks":3,"kind":"structured","sourceFormat":"oa-original-paper2","sourcePaperId":"OA-ORIGINAL-02-03","sourceQuestion":2,"sourcePartId":"q2-a","sourceVersion":"oa-paper2-original-2026-10-26-v1","sourceMarking":{"criteria":[{"id":"q2-a-c1","marks":1,"rule":"One distinct correct point (1 of 3); accept the alternatives in the source answer bank.","model":"A quorum is the minimum number of eligible members required for a valid meeting.","alternatives":[]},{"id":"q2-a-c2","marks":1,"rule":"One distinct correct point (2 of 3); accept the alternatives in the source answer bank.","model":"A motion is a formal proposal put to a meeting for consideration.","alternatives":[]},{"id":"q2-a-c3","marks":1,"rule":"One distinct correct point (3 of 3); accept the alternatives in the source answer bank.","model":"A resolution is a decision formally adopted by a meeting.","alternatives":[]}],"choiceBank":[{"model":"A quorum is the minimum number of eligible members required for a valid meeting.","alternatives":[]},{"model":"A motion is a formal proposal put to a meeting for consideration.","alternatives":[]},{"model":"A resolution is a decision formally adopted by a meeting.","alternatives":[]}]},"prompt":"Explain the meaning of a quorum, a motion and a resolution.","expectedAnswer":"A quorum is the minimum number of eligible members required for a valid meeting.\nA motion is a formal proposal put to a meeting for consideration.\nA resolution is a decision formally adopted by a meeting.","rubricVersion":"oa-source-rubric-v2-2026-10-26"},{"id":"OA-ORIGINAL-02-03-Q2::q2-b","maxMarks":4,"kind":"structured","sourceFormat":"oa-original-paper2","sourcePaperId":"OA-ORIGINAL-02-03","sourceQuestion":2,"sourcePartId":"q2-b","sourceVersion":"oa-paper2-original-2026-10-26-v1","sourceMarking":{"criteria":[{"id":"q2-b-c1","marks":1,"rule":"One distinct correct point (1 of 4); accept the alternatives in the source answer bank.","model":"The chairperson follows the agenda and keeps discussion relevant.","alternatives":[]},{"id":"q2-b-c2","marks":1,"rule":"One distinct correct point (2 of 4); accept the alternatives in the source answer bank.","model":"The chairperson gives eligible members a fair opportunity to contribute.","alternatives":[]},{"id":"q2-b-c3","marks":1,"rule":"One distinct correct point (3 of 4); accept the alternatives in the source answer bank.","model":"The chairperson maintains order and applies the meeting rules.","alternatives":[]},{"id":"q2-b-c4","marks":1,"rule":"One distinct correct point (4 of 4); accept the alternatives in the source answer bank.","model":"The chairperson clarifies motions and announces the result of decisions.","alternatives":[]}],"choiceBank":[{"model":"The chairperson follows the agenda and keeps discussion relevant.","alternatives":[]},{"model":"The chairperson gives eligible members a fair opportunity to contribute.","alternatives":[]},{"model":"The chairperson maintains order and applies the meeting rules.","alternatives":[]},{"model":"The chairperson clarifies motions and announces the result of decisions.","alternatives":[]},{"model":"The chairperson manages the available meeting time.","alternatives":[]}]},"prompt":"State FOUR duties of a chairperson during a meeting.","expectedAnswer":"The chairperson follows the agenda and keeps discussion relevant.\nThe chairperson gives eligible members a fair opportunity to contribute.\nThe chairperson maintains order and applies the meeting rules.\nThe chairperson clarifies motions and announces the result of decisions.","rubricVersion":"oa-source-rubric-v2-2026-10-26"},{"id":"OA-ORIGINAL-02-03-Q2::q2-c","maxMarks":8,"kind":"structured","sourceFormat":"oa-original-paper2","sourcePaperId":"OA-ORIGINAL-02-03","sourceQuestion":2,"sourcePartId":"q2-c","sourceVersion":"oa-paper2-original-2026-10-26-v1","sourceMarking":{"criteria":[{"id":"q2-c-c1","marks":1,"rule":"Committee: Training committee","kind":"field","label":"Committee","expected":"Training committee","alternatives":[],"labelAliases":[],"model":"Committee: Training committee"},{"id":"q2-c-c2","marks":1,"rule":"Date and venue: 8 November 2027, Room 2","kind":"field","label":"Date and venue","expected":"8 November 2027, Room 2","alternatives":["Room 2, 8 November 2027"],"labelAliases":[],"model":"Date and venue: 8 November 2027, Room 2"},{"id":"q2-c-c3","marks":1,"rule":"Chair: Ms Leila Henry","kind":"field","label":"Chair","expected":"Ms Leila Henry","alternatives":["Leila Henry"],"labelAliases":[],"model":"Chair: Ms Leila Henry"},{"id":"q2-c-c4","marks":1,"rule":"Previous minutes: Approved without amendment","kind":"field","label":"Previous minutes","expected":"Approved without amendment","alternatives":["Previous minutes approved with no changes"],"labelAliases":[],"model":"Previous minutes: Approved without amendment"},{"id":"q2-c-c5","marks":1,"rule":"Workshop decision: Customer-service workshop on 26 November 2027","kind":"field","label":"Workshop decision","expected":"Customer-service workshop on 26 November 2027","alternatives":["Hold a customer service workshop on 26 November 2027"],"labelAliases":[],"model":"Workshop decision: Customer-service workshop on 26 November 2027"},{"id":"q2-c-c6","marks":1,"rule":"Venue quotations: Mr David Bell to obtain two quotations by 12 November.","kind":"field","label":"Venue quotations","expected":"Mr David Bell to obtain two quotations by 12 November.","alternatives":["David Bell: obtain 2 venue quotations by 12 November 2027."],"labelAliases":[],"model":"Venue quotations: Mr David Bell to obtain two quotations by 12 November."},{"id":"q2-c-c7","marks":1,"rule":"Registration form: Ms Sara King to circulate it by 15 November.","kind":"field","label":"Registration form","expected":"Ms Sara King to circulate it by 15 November.","alternatives":["Sara King: circulate registration form by 15 November 2027."],"labelAliases":[],"model":"Registration form: Ms Sara King to circulate it by 15 November."},{"id":"q2-c-c8","marks":1,"rule":"Next meeting: 18 November 2027, 10:00 a.m.","kind":"field","label":"Next meeting","expected":"18 November 2027, 10:00 a.m.","alternatives":["18 November 2027 at 10 am","18 November 2027 10:00"],"labelAliases":[],"model":"Next meeting: 18 November 2027, 10:00 a.m."}]},"prompt":"Prepare the action minutes using these EIGHT labels: Committee; Date and venue; Chair; Previous minutes; Workshop decision; Venue quotations; Registration form; Next meeting.","expectedAnswer":"Committee: Training committee\nDate and venue: 8 November 2027, Room 2\nChair: Ms Leila Henry\nPrevious minutes: Approved without amendment\nWorkshop decision: Customer-service workshop on 26 November 2027\nVenue quotations: Mr David Bell to obtain two quotations by 12 November.\nRegistration form: Ms Sara King to circulate it by 15 November.\nNext meeting: 18 November 2027, 10:00 a.m.","rubricVersion":"oa-source-rubric-v2-2026-10-26"},{"id":"OA-ORIGINAL-02-03-Q3::q3-a","maxMarks":3,"kind":"structured","sourceFormat":"oa-original-paper2","sourcePaperId":"OA-ORIGINAL-02-03","sourceQuestion":3,"sourcePartId":"q3-a","sourceVersion":"oa-paper2-original-2026-10-26-v1","sourceMarking":{"criteria":[{"id":"q3-a-c1","marks":1,"rule":"One distinct correct point (1 of 3); accept the alternatives in the source answer bank.","model":"An itinerary gives the traveller the sequence and timing of the planned journey.","alternatives":[]},{"id":"q3-a-c2","marks":1,"rule":"One distinct correct point (2 of 3); accept the alternatives in the source answer bank.","model":"An itinerary helps the office contact the traveller or locate the relevant booking.","alternatives":[]},{"id":"q3-a-c3","marks":1,"rule":"One distinct correct point (3 of 3); accept the alternatives in the source answer bank.","model":"An itinerary helps identify gaps or clashes between travel and business appointments.","alternatives":[]}],"choiceBank":[{"model":"An itinerary gives the traveller the sequence and timing of the planned journey.","alternatives":[]},{"model":"An itinerary helps the office contact the traveller or locate the relevant booking.","alternatives":[]},{"model":"An itinerary helps identify gaps or clashes between travel and business appointments.","alternatives":[]},{"model":"An itinerary provides a record for checking reservations and making agreed changes.","alternatives":[]}]},"prompt":"State THREE advantages of keeping an up-to-date business travel itinerary.","expectedAnswer":"An itinerary gives the traveller the sequence and timing of the planned journey.\nAn itinerary helps the office contact the traveller or locate the relevant booking.\nAn itinerary helps identify gaps or clashes between travel and business appointments.","rubricVersion":"oa-source-rubric-v2-2026-10-26"},{"id":"OA-ORIGINAL-02-03-Q3::q3-b","maxMarks":4,"kind":"structured","sourceFormat":"oa-original-paper2","sourcePaperId":"OA-ORIGINAL-02-03","sourceQuestion":3,"sourcePartId":"q3-b","sourceVersion":"oa-paper2-original-2026-10-26-v1","sourceMarking":{"criteria":[{"id":"q3-b-c1","marks":1,"rule":"One distinct correct point (1 of 4); accept the alternatives in the source answer bank.","model":"The system should allow authorised users to retrieve records quickly.","alternatives":[]},{"id":"q3-b-c2","marks":1,"rule":"One distinct correct point (2 of 4); accept the alternatives in the source answer bank.","model":"The classification and indexing rules should be clear and consistent.","alternatives":[]},{"id":"q3-b-c3","marks":1,"rule":"One distinct correct point (3 of 4); accept the alternatives in the source answer bank.","model":"The system should protect records against unauthorised access or loss.","alternatives":[]},{"id":"q3-b-c4","marks":1,"rule":"One distinct correct point (4 of 4); accept the alternatives in the source answer bank.","model":"The system should be capable of expanding as the number of records grows.","alternatives":[]}],"choiceBank":[{"model":"The system should allow authorised users to retrieve records quickly.","alternatives":[]},{"model":"The classification and indexing rules should be clear and consistent.","alternatives":[]},{"model":"The system should protect records against unauthorised access or loss.","alternatives":[]},{"model":"The system should be capable of expanding as the number of records grows.","alternatives":[]},{"model":"The system should suit the types of records and the needs of users.","alternatives":[]}]},"prompt":"Identify FOUR features of an effective filing system.","expectedAnswer":"The system should allow authorised users to retrieve records quickly.\nThe classification and indexing rules should be clear and consistent.\nThe system should protect records against unauthorised access or loss.\nThe system should be capable of expanding as the number of records grows.","rubricVersion":"oa-source-rubric-v2-2026-10-26"},{"id":"OA-ORIGINAL-02-03-Q3::q3-c","maxMarks":8,"kind":"structured","sourceFormat":"oa-original-paper2","sourcePaperId":"OA-ORIGINAL-02-03","sourceQuestion":3,"sourcePartId":"q3-c","sourceVersion":"oa-paper2-original-2026-10-26-v1","sourceMarking":{"criteria":[{"id":"q3-c-c1","marks":1,"rule":"First file: Brown, Aaron","kind":"field","label":"First file","expected":"Brown, Aaron","alternatives":[],"labelAliases":[],"model":"First file: Brown, Aaron"},{"id":"q3-c-c2","marks":1,"rule":"Second file: Brown, Alice","kind":"field","label":"Second file","expected":"Brown, Alice","alternatives":[],"labelAliases":[],"model":"Second file: Brown, Alice"},{"id":"q3-c-c3","marks":1,"rule":"Third file: Browne, Carl","kind":"field","label":"Third file","expected":"Browne, Carl","alternatives":[],"labelAliases":[],"model":"Third file: Browne, Carl"},{"id":"q3-c-c4","marks":1,"rule":"Fourth file: Clarke, Denise","kind":"field","label":"Fourth file","expected":"Clarke, Denise","alternatives":[],"labelAliases":[],"model":"Fourth file: Clarke, Denise"},{"id":"q3-c-c5","marks":1,"rule":"Passport check: Check passport validity against the destination’s entry requirements.","kind":"field","label":"Passport check","expected":"Check passport validity against the destination’s entry requirements.","alternatives":["Check passport validity and destination entry requirements."],"labelAliases":[],"model":"Passport check: Check passport validity against the destination’s entry requirements."},{"id":"q3-c-c6","marks":1,"rule":"Hotel confirmation: Obtain written confirmation of the hotel reservation.","kind":"field","label":"Hotel confirmation","expected":"Obtain written confirmation of the hotel reservation.","alternatives":["Confirm the hotel booking in writing."],"labelAliases":[],"model":"Hotel confirmation: Obtain written confirmation of the hotel reservation."},{"id":"q3-c-c7","marks":1,"rule":"Itinerary copy: Give the traveller and the authorised office contact the current itinerary.","kind":"field","label":"Itinerary copy","expected":"Give the traveller and the authorised office contact the current itinerary.","alternatives":["Provide the current itinerary to the traveller and authorised office contact."],"labelAliases":[],"model":"Itinerary copy: Give the traveller and the authorised office contact the current itinerary."},{"id":"q3-c-c8","marks":1,"rule":"Change control: Update the itinerary and notify the traveller and relevant office contact after an agreed change.","kind":"field","label":"Change control","expected":"Update the itinerary and notify the traveller and relevant office contact after an agreed change.","alternatives":["Record agreed changes and send the updated itinerary to the traveller and office contact."],"labelAliases":[],"model":"Change control: Update the itinerary and notify the traveller and relevant office contact after an agreed change."}]},"prompt":"Complete the filing and travel checklist using these EIGHT labels: First file; Second file; Third file; Fourth file; Passport check; Hotel confirmation; Itinerary copy; Change control.","expectedAnswer":"First file: Brown, Aaron\nSecond file: Brown, Alice\nThird file: Browne, Carl\nFourth file: Clarke, Denise\nPassport check: Check passport validity against the destination’s entry requirements.\nHotel confirmation: Obtain written confirmation of the hotel reservation.\nItinerary copy: Give the traveller and the authorised office contact the current itinerary.\nChange control: Update the itinerary and notify the traveller and relevant office contact after an agreed change.","rubricVersion":"oa-source-rubric-v2-2026-10-26"},{"id":"OA-ORIGINAL-02-03-Q4::q4-a","maxMarks":3,"kind":"structured","sourceFormat":"oa-original-paper2","sourcePaperId":"OA-ORIGINAL-02-03","sourceQuestion":4,"sourcePartId":"q4-a","sourceVersion":"oa-paper2-original-2026-10-26-v1","sourceMarking":{"criteria":[{"id":"q4-a-c1","marks":1,"rule":"One distinct correct point (1 of 3); accept the alternatives in the source answer bank.","model":"The records support correct pay and authorised leave calculations.","alternatives":[]},{"id":"q4-a-c2","marks":1,"rule":"One distinct correct point (2 of 3); accept the alternatives in the source answer bank.","model":"The records help the organisation plan staffing and cover absences.","alternatives":[]},{"id":"q4-a-c3","marks":1,"rule":"One distinct correct point (3 of 3); accept the alternatives in the source answer bank.","model":"The records provide evidence when attendance patterns need to be discussed.","alternatives":[]}],"choiceBank":[{"model":"The records support correct pay and authorised leave calculations.","alternatives":[]},{"model":"The records help the organisation plan staffing and cover absences.","alternatives":[]},{"model":"The records provide evidence when attendance patterns need to be discussed.","alternatives":[]},{"model":"The records support fair and consistent application of leave procedures.","alternatives":[]}]},"prompt":"State THREE reasons for keeping accurate attendance and leave records.","expectedAnswer":"The records support correct pay and authorised leave calculations.\nThe records help the organisation plan staffing and cover absences.\nThe records provide evidence when attendance patterns need to be discussed.","rubricVersion":"oa-source-rubric-v2-2026-10-26"},{"id":"OA-ORIGINAL-02-03-Q4::q4-b","maxMarks":3,"kind":"structured","sourceFormat":"oa-original-paper2","sourcePaperId":"OA-ORIGINAL-02-03","sourceQuestion":4,"sourcePartId":"q4-b","sourceVersion":"oa-paper2-original-2026-10-26-v1","sourceMarking":{"criteria":[{"id":"q4-b-c1","marks":1,"rule":"One distinct correct point (1 of 3); accept the alternatives in the source answer bank.","model":"The employee should receive appropriate help from the designated first-aider or emergency services.","alternatives":[]},{"id":"q4-b-c2","marks":1,"rule":"One distinct correct point (2 of 3); accept the alternatives in the source answer bank.","model":"The supervisor should be informed and the incident should be recorded promptly.","alternatives":[]},{"id":"q4-b-c3","marks":1,"rule":"One distinct correct point (3 of 3); accept the alternatives in the source answer bank.","model":"The immediate hazard should be made safe without creating further danger.","alternatives":[]}],"choiceBank":[{"model":"The employee should receive appropriate help from the designated first-aider or emergency services.","alternatives":[]},{"model":"The supervisor should be informed and the incident should be recorded promptly.","alternatives":[]},{"model":"The immediate hazard should be made safe without creating further danger.","alternatives":[]},{"model":"The organisation should investigate the cause and arrange appropriate corrective action.","alternatives":[]}]},"prompt":"Outline THREE appropriate actions when an employee is injured at work.","expectedAnswer":"The employee should receive appropriate help from the designated first-aider or emergency services.\nThe supervisor should be informed and the incident should be recorded promptly.\nThe immediate hazard should be made safe without creating further danger.","rubricVersion":"oa-source-rubric-v2-2026-10-26"},{"id":"OA-ORIGINAL-02-03-Q4::q4-c","maxMarks":9,"kind":"structured","sourceFormat":"oa-original-paper2","sourcePaperId":"OA-ORIGINAL-02-03","sourceQuestion":4,"sourcePartId":"q4-c","sourceVersion":"oa-paper2-original-2026-10-26-v1","sourceMarking":{"criteria":[{"id":"q4-c-c1","marks":1,"rule":"Employee: Joel Reed","kind":"field","label":"Employee","expected":"Joel Reed","alternatives":[],"labelAliases":[],"model":"Employee: Joel Reed"},{"id":"q4-c-c2","marks":1,"rule":"Date: 10 November 2027","kind":"field","label":"Date","expected":"10 November 2027","alternatives":[],"labelAliases":[],"model":"Date: 10 November 2027"},{"id":"q4-c-c3","marks":1,"rule":"Time: 2:10 p.m.","kind":"field","label":"Time","expected":"2:10 p.m.","alternatives":["2:10 pm","14:10"],"labelAliases":[],"model":"Time: 2:10 p.m."},{"id":"q4-c-